import json
from datetime import date

def due_tasks(tasks, today):
    result = [t for t in tasks if date.fromisoformat(t["due"]) <= today]
    return sorted(result, key=lambda t: (t["due"], t["name"]))

today = date.fromisoformat(input())
with open("tasks.json", encoding="utf-8") as f:
    tasks = json.load(f)
overdue = due_tasks(tasks, today)
if overdue:
    for t in overdue:
        print("DUE " + t["due"] + " " + t["name"])
else:
    print("nothing due")

from datetime import date, timedelta

def next_due(due, every_days, today):
    d = date.fromisoformat(due)
    if every_days <= 0:
        return None
    while d <= today:
        d = d + timedelta(days=every_days)
    return d.isoformat()

