import json
from datetime import date, timedelta

def next_due(due, every_days, today):
    d = date.fromisoformat(due)
    if every_days <= 0:
        return None
    while d <= today:
        d = d + timedelta(days=every_days)
    return d.isoformat()

today = date.fromisoformat(input())
with open("tasks.json", encoding="utf-8") as f:
    tasks = json.load(f)
lines = []
for t in sorted(tasks, key=lambda t: (t["due"], t["name"])):
    d = date.fromisoformat(t["due"])
    if d <= today:
        days = (today - d).days
        nxt = next_due(t["due"], t["every_days"], today)
        lines.append("OVERDUE " + t["name"] + " by " + str(days) + "d next=" + str(nxt))
print("\n".join(lines) if lines else "nothing due")
